declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('services.assign');$id=max(1,(int)($_GET['id']??$_POST['id']??0));$st=db()->prepare("SELECT d.*,c.company_name FROM deals d LEFT JOIN clients c ON c.id=d.client_id WHERE d.id=?");$st->execute([$id]);$deal=$st->fetch();if(!$deal){http_response_code(404);exit('Negocio no encontrado.');}if(!$deal['client_id']){flash('error','Asigna un cliente al negocio antes de convertirlo.');redirect('deal_view.php?id='.$id);}$existing=db()->prepare('SELECT id FROM client_services WHERE deal_id=? LIMIT 1');$existing->execute([$id]);if($sid=(int)($existing->fetchColumn()?:0)){flash('success','Este negocio ya fue convertido en servicio activo.');redirect('service_form.php?id='.$sid);}
$pageTitle='Convertir negocio en servicio activo';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=(string)($_POST['contract_type']??'monthly');if(!in_array($type,['monthly','annual','one_time','custom'],true))$type='monthly';$custom=$type==='custom'?max(1,(int)($_POST['custom_period_months']??1)):null;$start=(string)($_POST['start_date']??date('Y-m-d'));$next=(string)($_POST['next_billing_date']??'');if(!$next)$next=billing_next_date($start,$type,$custom)?:$start;$name=trim((string)($_POST['name']??$deal['title']));$amount=max(0,(float)($_POST['amount']??$deal['amount']));$currency=(string)($_POST['currency']??$deal['currency']);$alerts=trim((string)($_POST['alert_days']??'30,15,7,3,1,0'))?:'30,15,7,3,1,0';if($name==='')$errors[]='Indica el nombre del servicio.';if(!$errors){db()->prepare("INSERT INTO client_services(client_id,deal_id,name,contract_type,custom_period_months,start_date,expiration_date,next_billing_date,amount,currency,payment_status,billing_status,alert_days,billing_notify_email,billing_notify_whatsapp,billing_notify_inapp,auto_renew,status,notes) VALUES (?,?,?,?,?,?,?,?,?,?, 'pending','pending',?,?,?,?,?, 'active',?)")->execute([(int)$deal['client_id'],$id,$name,$type,$custom,$start,$next,$next,$amount,$currency,$alerts,isset($_POST['notify_email'])?1:0,isset($_POST['notify_whatsapp'])?1:0,isset($_POST['notify_inapp'])?1:0,$type==='one_time'?0:1,trim((string)($_POST['notes']??''))?:null]);$sid=(int)db()->lastInsertId();$s=db()->prepare('SELECT * FROM client_services WHERE id=?');$s->execute([$sid]);billing_sync_charge($s->fetch());log_activity('Negocio convertido en servicio activo',(int)$deal['client_id'],$sid,$deal['title']);flash('success','Negocio convertido. Ya aparece en Facturación y Renovaciones.');redirect('billing_services.php');}}
require __DIR__.'/includes/header.php';?><?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2><?=e($deal['title'])?></h2><span class="table-sub"><?=e($deal['company_name'])?> · <?=e(format_money($deal['amount'],$deal['currency']))?></span></div><a class="btn btn-light" href="deal_view.php?id=<?=$id?>">Cancelar</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Servicio / contrato<input name="name" required value="<?=e($deal['title'])?>"></label><label>Modalidad<select name="contract_type"><option value="monthly">Mensual</option><option value="annual">Anual</option><option value="one_time">Pago único</option><option value="custom">Cada X meses</option></select></label><label>Meses si es personalizado<input type="number" min="1" name="custom_period_months" value="3"></label><label>Fecha de inicio<input type="date" name="start_date" value="<?=date('Y-m-d')?>"></label><label>Próximo cobro / renovación<input type="date" name="next_billing_date"><span class="table-sub">Si lo dejas vacío se calcula automáticamente.</span></label><label>Valor<input type="number" step="0.01" min="0" name="amount" value="<?=e($deal['amount'])?>"></label><label>Moneda<select name="currency"><?php foreach(['CLP','USD','BRL']as$c):?><option <?=$deal['currency']===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select></label><label>Días de alerta<input name="alert_days" value="30,15,7,3,1,0"></label><label class="checkbox-row"><input type="checkbox" name="notify_email" checked> Email</label><label class="checkbox-row"><input type="checkbox" name="notify_inapp" checked> CRM</label><label class="checkbox-row"><input type="checkbox" name="notify_whatsapp"> WhatsApp</label><label class="full">Notas<textarea name="notes"><?=e($deal['notes']?:'')?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="deal_view.php?id=<?=$id?>">Cancelar</a><button class="btn btn-primary">CREAR SERVICIO ACTIVO</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
